// Un AsyncStorage de mentira que cuenta cuántas veces se escribe.
const disco = new Map();
let escrituras = 0;
const falso = { setItem: (k, v) => { escrituras++; disco.set(k, v); } };

// Guardar en cada cambio.
function inmediato() {
  return { guardar: (k, v) => falso.setItem(k, JSON.stringify(v)) };
}

// El patrón de Senda: juntar los cambios y escribir 400 ms después del primero.
function enLotes(esperaMs) {
  const pendientes = new Map();
  let reloj = null;
  function guardarYa() {
    clearTimeout(reloj);
    reloj = null;
    for (const [k, v] of pendientes) falso.setItem(k, JSON.stringify(v));
    pendientes.clear();
  }
  return {
    guardar(k, v) { pendientes.set(k, v); if (!reloj) reloj = setTimeout(guardarYa, esperaMs); },
    guardarYa,
  };
}

const a = inmediato();
for (let i = 1; i <= 30; i++) a.guardar("usuario", { talentos: i });
console.log("guardando en cada cambio:", escrituras, "escrituras");

escrituras = 0;
const b = enLotes(400);
for (let i = 1; i <= 30; i++) b.guardar("usuario", { talentos: i });
console.log("en lotes, a los 0 ms:    ", escrituras, "escrituras");
await new Promise((r) => setTimeout(r, 450));
console.log("en lotes, a los 450 ms:  ", escrituras, "escritura; guardado =", disco.get("usuario"));

// Si la app pasa a segundo plano antes de los 400 ms, se escribe en el acto.
escrituras = 0;
const c = enLotes(400);
c.guardar("usuario", { talentos: 99 });
c.guardarYa();
console.log("con guardarYa():         ", escrituras, "escritura, sin esperar el reloj; guardado =", disco.get("usuario"));
